import stylesText from './line-editor.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatMacro, macroSegments } from '../../../../utils/format-macro.js';
import { unitLabel, viewNutrition, withAmount, type LineView } from '../../../../utils/line-view.js';
import { LINE_NUTRIENTS, lineNutrition, type LineNutrient } from '@motivation/shared';
import {
    HEALTH_EVENTS,
    createLineEditorRemoveEvent,
    createLineEditorSaveEvent,
    type AmountChangeEvent,
} from '../../health-events.js';
import { dispatchAndSettle, whileBusy } from '../../../../utils/in-flight.js';
import '../amount-input/amount-input.component.js';
import '../nutrition-summary/nutrition-summary.component.js';
import type { AmountInput } from '../amount-input/amount-input.component.js';
import type { NutritionSummary } from '../nutrition-summary/nutrition-summary.component.js';

const styles = cssStyleSheet(stylesText);

const NUTRIENT_LABELS: Record<LineNutrient, string> = {
    calories: 'kcal', protein_g: 'protein g', carbs_g: 'carbs g', fat_g: 'fat g', fiber_g: 'fiber g', sugar_g: 'sugar g', sodium_mg: 'sodium mg',
};

const template = document.createElement('template');
template.innerHTML = `
    <section class="card nutrition">
        <nutrition-summary variant="hero"></nutrition-summary>
        <nutrition-summary variant="chips"></nutrition-summary>
        <div class="override-fields" hidden>
            ${LINE_NUTRIENTS.map((n) => `
                <label class="field"><span>${NUTRIENT_LABELS[n]}</span>
                    <input data-nutrient="${n}" inputmode="decimal" autocomplete="off"></label>`).join('')}
        </div>
    </section>
    <section class="card amount">
        <div class="amount-head"><span>Amount</span></div>
        <amount-input size="large" presets></amount-input>
        <button type="button" class="reset">Reset</button>
        <p class="per-base" hidden></p>
    </section>
    <label class="override-toggle"><input type="checkbox" class="override"> Override nutrition for this line only</label>
    <p class="error" role="alert" hidden></p>
    <div class="actions">
        <button type="button" class="remove" hidden>Remove</button>
        <button type="button" class="done">Done</button>
    </div>
`;

/**
 * Story 420 — one line in depth (418 #9): its nutrition, the amount with presets and Reset, the
 * food's basis, and an override (story 368) that replaces the computed nutrients for this line
 * only. Nothing is written: Done emits `health:line-editor-save` with the amount and the
 * override (null when off); Remove (`removable`) emits `health:line-editor-remove`.
 */
export class LineEditor extends HTMLElement {
    static get observedAttributes() { return ['removable']; }

    private initial: LineView | null = null;
    private view: LineView | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        customElements.upgrade(shadow);

        (shadow.querySelector('amount-input') as AmountInput).addEventListener(HEALTH_EVENTS.AMOUNT_CHANGE, (e: AmountChangeEvent) => {
            e.stopPropagation();
            if (this.view) this.update(withAmount(this.view, e.detail.value));
        });
        shadow.querySelector('.reset')!.addEventListener('click', () => {
            if (this.view && this.initial) this.update(withAmount(this.view, this.initial.amount));
        });
        this.overrideBox.addEventListener('change', () => {
            if (!this.view) return;
            // On: start from what the line shows now. Off: back to the food's (or snapshot's) numbers.
            const { override: _dropped, ...rest } = this.view;
            this.update(this.overrideBox.checked ? { ...rest, override: viewNutrition(this.view) } : rest);
        });
        for (const input of this.fields()) {
            input.addEventListener('input', () => {
                if (!this.view) return;
                const n = input.dataset.nutrient as LineNutrient;
                const value = parseNutrient(input.value);
                input.toggleAttribute('aria-invalid', value === undefined);
                if (value !== undefined) this.update({ ...this.view, override: { ...this.view.override, [n]: value } }, { keepFields: true });
            });
        }
        // Story 371: each button stays disabled until the screen's write settles — a double tap writes once.
        const done = shadow.querySelector('.done') as HTMLButtonElement;
        done.addEventListener('click', () => void whileBusy(done, () => this.save()));
        const remove = shadow.querySelector('.remove') as HTMLButtonElement;
        remove.addEventListener('click', () => void whileBusy(remove, () => dispatchAndSettle(this, createLineEditorRemoveEvent())));
    }

    get line(): LineView | null { return this.view; }
    set line(value: LineView) {
        this.initial = value;
        this.update(value);
    }

    /** Story 434: show `amount` as a change to the line — Reset goes back to what it was. */
    propose(amount: number): void {
        if (this.view) this.update(withAmount(this.view, amount));
    }

    attributeChangedCallback(): void { this.render(); }

    private get overrideBox(): HTMLInputElement {
        return this.shadowRoot!.querySelector('.override') as HTMLInputElement;
    }

    private fields(): HTMLInputElement[] {
        return [...this.shadowRoot!.querySelectorAll<HTMLInputElement>('.override-fields input')];
    }

    private update(view: LineView, options: { keepFields?: boolean } = {}): void {
        this.view = view;
        this.render(options);
    }

    private async save(): Promise<void> {
        const view = this.view;
        if (!view) return;
        const invalid = this.fields().filter((f) => f.hasAttribute('aria-invalid'));
        const error = this.shadowRoot!.querySelector('.error') as HTMLElement;
        const amount = (this.shadowRoot!.querySelector('amount-input') as AmountInput).valid();
        if (amount === null || invalid.length > 0) {
            error.textContent = amount === null ? 'Enter an amount above 0.' : `Not a number ≥ 0: ${invalid.map((f) => NUTRIENT_LABELS[f.dataset.nutrient as LineNutrient]).join(', ')}`;
            error.hidden = false;
            return;
        }
        error.hidden = true;
        return dispatchAndSettle(this, createLineEditorSaveEvent({ amount: view.amount, override: view.override ?? null }));
    }

    private render(options: { keepFields?: boolean } = {}): void {
        const shadow = this.shadowRoot!;
        (shadow.querySelector('.remove') as HTMLElement).hidden = !this.hasAttribute('removable');
        const view = this.view;
        if (!view) return;
        const n = viewNutrition(view);
        for (const s of shadow.querySelectorAll<NutritionSummary>('nutrition-summary')) s.nutrition = n;
        const input = shadow.querySelector('amount-input') as AmountInput;
        input.setAttribute('unit', view.unit);
        input.setAttribute('label', `${view.name}, ${unitLabel(view.unit)}`);
        if (input.value !== view.amount) input.value = view.amount;

        const perBase = shadow.querySelector('.per-base') as HTMLElement;
        perBase.hidden = view.basis.kind !== 'food';
        if (view.basis.kind === 'food') {
            const base = view.basis.food.base_amount;
            const per = lineNutrition(view.basis.food, base);
            perBase.replaceChildren(...macroSegments(`Per ${formatMacro(base)} ${unitLabel(view.unit)}: ${formatMacro(per.calories)} kcal · P ${formatMacro(per.protein_g)} · C ${formatMacro(per.carbs_g)} · F ${formatMacro(per.fat_g)}`));
        }

        const overriding = view.override !== undefined;
        this.overrideBox.checked = overriding;
        (shadow.querySelector('.override-fields') as HTMLElement).hidden = !overriding;
        if (overriding && !options.keepFields) {
            for (const f of this.fields()) {
                const v = n[f.dataset.nutrient as LineNutrient];
                f.value = v === null ? '' : formatMacro(v);
                f.removeAttribute('aria-invalid');
            }
        }
    }
}

/** A nutrient as typed: a number ≥ 0, empty for unknown (null), anything else undefined (invalid). */
function parseNutrient(text: string): number | null | undefined {
    const t = text.trim().replace(',', '.');
    if (t === '') return null;
    const n = Number(t);
    return Number.isFinite(n) && n >= 0 ? n : undefined;
}

if (!customElements.get('line-editor')) {
    customElements.define('line-editor', LineEditor);
}
